      newTags.splice(index, 1);
      this.$emit('update:tags', newTags);
    },
  },
});
```

In this example, we define a `TagList` component that takes an array of tag strings as a prop. The `render` method maps over the tags and renders each one with a remove button. When the "Remove" button is clicked, it emits an event to update the `tags` prop by removing the corresponding tag.

